module packing_solver (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [15:0] N,\n    output reg [15:0] result,\n    output reg done\n);\n\n    // State definitions\n    localparam [2:0] IDLE        = 3'd0;\n    localparam [2:0] INIT        = 3'd1;\n    localparam [2:0] COMPUTE_W   = 3'd2;\n    localparam [2:0] CHECK_RATIO = 3'd3;\n    localparam [2:0] UPDATE_MIN  = 3'd4;\n    localparam [2:0] INCREMENT_H = 3'd5;\n    localparam [2:0] DONE_STATE  = 3'd6;\n\n    reg [2:0] state;\n    reg [15:0] H;\n    reg [15:0] W;\n    reg [15:0] min_empty;\n    reg [31:0] area;\n    reg [3:0] cycles;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            result <= 16'd0;\n            H <= 16'd0;\n            min_empty <= 16'hFFFF;\n            W <= 16'd0;\n            area <= 32'd0;\n            cycles <= 4'd0;\n        end \n        else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) state <= INIT;\n                end\n                \n                INIT: begin\n                    H <= 16'd1;\n                    min_empty <= 16'hFFFF;\n                    state <= COMPUTE_W;\n                end\n                \n                COMPUTE_W: begin\n                    if (H == 16'd0) W <= 16'd0;\n                    else W <= (N + H - 1) / H;\n                    state <= CHECK_RATIO;\n                end\n                \n                CHECK_RATIO: begin\n                    if ((W >= (H >> 1)) && (W <= (H << 1)) && ((W * H) >= N))\n                        area <= W * H;\n                    else \n                        area <= 32'hFFFFFFFF;\n                    state <= UPDATE_MIN;\n                end\n                \n                UPDATE_MIN: begin\n                    if (area != 32'hFFFFFFFF) begin\n                        if ((area - N) < min_empty)\n                            min_empty <= area - N;\n                    end\n                    state <= INCREMENT_H;\n                end\n                \n                INCREMENT_H: begin\n                    cycles <= cycles + 4'd1;\n                    if (H < 16'd256) begin\n                        H <= H + 16'd1;\n                        state <= COMPUTE_W;\n                    end\n                    else state <= DONE_STATE;\n                end\n                \n                DONE_STATE: begin\n                    result <= min_empty;\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule